def is_palindrome(x: int) -> bool:
    x = str(x)
    for i in range(len(x) // 2):
        if x[i] != x[-i - 1]:
            return False
    return True

def find_max_palindromic_cube(n: int) -> int:
    ans = 0
    i = 1
    while True:
        cube = i ** 3
        if cube <= n and is_palindrome(cube):
            ans = cube
        elif cube > n:
            break
        i += 1
    return ans

n = int(input())
print(find_max_palindromic_cube(n))
